import{_ as e,o as t,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"HJ70 矩阵乘法计算量估算","description":"中等 通过率：40.49% 时间限制：1秒 空间限制：32M 知识点 字符串 栈 描述 矩阵乘法的运算量与矩阵乘法的顺序强相关。 例如： A是一个50×10的矩阵，B是10×20的矩阵，C是20×5的矩阵 计算A B C有两种顺序：((AB)C)或者(A(BC))，前者需要计算1。","frontmatter":{"title":"HJ70 矩阵乘法计算量估算","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：40.49% 时间限制：1秒 空间限制：32M 知识点 字符串 栈 描述 矩阵乘法的运算量与矩阵乘法的顺序强相关。 例如： A是一个50×10的矩阵，B是10×20的矩阵，C是20×5的矩阵 计算A B C有两种顺序：((AB)C)或者(A(BC))，前者需要计算1。","sidebarWeight":108,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/特定算法/HJ70 矩阵乘法计算量估算.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/特定算法/HJ70 矩阵乘法计算量估算.md","filePath":"posts/前端面试与实战/03-算法训练/特定算法/HJ70 矩阵乘法计算量估算.md"}'),i={name:"posts/前端面试与实战/03-算法训练/特定算法/HJ70 矩阵乘法计算量估算.md"};function n(s,a,l,m,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<div><h1 id="hj70-矩阵乘法计算量估算" tabindex="-1">HJ70 矩阵乘法计算量估算 <a class="header-anchor" href="#hj70-矩阵乘法计算量估算" aria-label="Permalink to &quot;HJ70 矩阵乘法计算量估算&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ70 矩阵乘法计算量估算”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：40.49% 时间限制：1秒 空间限制：32M 知识点==字符串====栈== <strong>描述</strong> 矩阵乘法的运算量与矩阵乘法的顺序强相关。 例如： A是一个50×10的矩阵，B是10×20的矩阵，C是20×5的矩阵 计算A<em>B</em>C有两种顺序：((AB)C)或者(A(BC))，前者需要计算15000次乘法，后者只需要3500次。 编写程序计算不同的计算顺序需要进行的乘法次数。 数据范围：矩阵个数： 1≤<em>n</em>≤15 ，行列数：1≤<em>rowi</em>,<em>coli</em>≤100 ，保证给出的字符串表示的计算顺序唯一。 进阶：时间复杂度：<em>O</em>(<em>n</em>) ，空间复杂度：<em>O</em>(<em>n</em>) <strong>输入描述：</strong> 输入多行，先输入要计算乘法的矩阵个数n，每个矩阵的行数，列数，总共2n的数，最后输入要计算的法则 计算的法则为一个字符串，仅由左右括号和大写字母（&#39;A&#39;~&#39;Z&#39;）组成，保证括号是匹配的且输入合法！ <strong>输出描述：</strong> 输出需要进行的乘法次数 <strong>示例1</strong> 输入： 350 1010 2020 5(A(BC)) ==复制== 输出： 3500</p></blockquote><p>这个问题是关于矩阵链乘法的优化问题，一个经典的动态规划问题。但是，根据输入的规则字符串来直接计算乘法次数的要求使得这个问题有点独特。我们可以使用栈来模拟计算过程，直接根据给定的顺序来计算乘法次数。</p><h3 id="思路" tabindex="-1">思路： <a class="header-anchor" href="#思路" aria-label="Permalink to &quot;思路：&quot;">​</a></h3><ol><li>首先，将每个矩阵的行列数读入并存储。</li><li>然后，遍历计算法则字符串。每遇到一个左括号&#39;(&#39;，我们预期会有一个矩阵乘法发生，直到遇到相应的右括号&#39;)&#39;，这时我们计算这个特定乘法操作的乘法次数，并将结果&quot;矩阵&quot;的行列数压栈，以便用于后续的乘法计算。</li><li>每次遇到矩阵（用字母表示）时，我们根据字母的顺序（&#39;A&#39;、&#39;B&#39;、&#39;C&#39;等）来获取其对应的行列数，并将其压栈。</li><li>遇到右括号时，弹出栈顶的两个矩阵，计算它们的乘法次数，并将新的&quot;矩阵&quot;行列数压回栈中。</li></ol><h3 id="示例代码" tabindex="-1">示例代码： <a class="header-anchor" href="#示例代码" aria-label="Permalink to &quot;示例代码：&quot;">​</a></h3><p>def matrix_multiply_cost(matrices, formula):</p><h1 id="将矩阵信息存储在字典中-方便查找" tabindex="-1">将矩阵信息存储在字典中，方便查找 <a class="header-anchor" href="#将矩阵信息存储在字典中-方便查找" aria-label="Permalink to &quot;将矩阵信息存储在字典中，方便查找&quot;">​</a></h1><p>matrix_dict = {chr(65+i): matrices[i] for i in range(len(matrices))} stack = [] # 使用栈来辅助计算 cost = 0 # 记录总的乘法次数 for char in formula: if char == &#39;)&#39;:</p><h1 id="遇到右括号-计算并合并栈顶的两个矩阵" tabindex="-1">遇到右括号，计算并合并栈顶的两个矩阵 <a class="header-anchor" href="#遇到右括号-计算并合并栈顶的两个矩阵" aria-label="Permalink to &quot;遇到右括号，计算并合并栈顶的两个矩阵&quot;">​</a></h1><p>m2 = stack.pop() m1 = stack.pop()</p><h1 id="计算乘法次数-m1的行数-m1的列数-即m2的行数-m2的列数" tabindex="-1">计算乘法次数：m1的行数 * m1的列数（即m2的行数） * m2的列数 <a class="header-anchor" href="#计算乘法次数-m1的行数-m1的列数-即m2的行数-m2的列数" aria-label="Permalink to &quot;计算乘法次数：m1的行数 * m1的列数（即m2的行数） * m2的列数&quot;">​</a></h1><p>current_cost = m1[0] * m1[1] * m2[1] cost += current_cost</p><h1 id="将新的矩阵行列数压栈" tabindex="-1">将新的矩阵行列数压栈 <a class="header-anchor" href="#将新的矩阵行列数压栈" aria-label="Permalink to &quot;将新的矩阵行列数压栈&quot;">​</a></h1><p>stack.append((m1[0], m2[1])) elif char in matrix_dict:</p><h1 id="遇到矩阵标识符-将其行列数压栈" tabindex="-1">遇到矩阵标识符，将其行列数压栈 <a class="header-anchor" href="#遇到矩阵标识符-将其行列数压栈" aria-label="Permalink to &quot;遇到矩阵标识符，将其行列数压栈&quot;">​</a></h1><p>stack.append(matrix_dict[char]) return cost</p><h1 id="读取输入" tabindex="-1">读取输入 <a class="header-anchor" href="#读取输入" aria-label="Permalink to &quot;读取输入&quot;">​</a></h1><p>n = int(input().strip()) # 矩阵个数 matrices = [] for _ in range(n): r, c = map(int, input().strip().split()) # 读取矩阵的行数和列数 matrices.append((r, c)) formula = input().strip() # 读取计算法则字符串</p><h1 id="计算并输出乘法次数" tabindex="-1">计算并输出乘法次数 <a class="header-anchor" href="#计算并输出乘法次数" aria-label="Permalink to &quot;计算并输出乘法次数&quot;">​</a></h1><p>print(matrix_multiply_cost(matrices, formula))</p><p>这个解法直接依据输入的计算顺序，通过模拟这个过程来计算乘法次数，避免了复杂的动态规划算法。需要注意的是，这种方法假设输入的计算顺序是合理的，即每次乘法操作都是可行的。</p></div>',1)])])}const u=e(i,[["render",n]]);export{d as __pageData,u as default};
